const items = $input.all();
return items.map(item => {
  let html = item.json.data || '';
  const statusCode = item.json.statusCode || 0;

  let cleaned = html.replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '');
  cleaned = cleaned.replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '');
  cleaned = cleaned.replace(/<[^>]+>/g, ' ');
  cleaned = cleaned.replace(/\s+/g, ' ').trim();
  cleaned = cleaned.substring(0, 5000);

  const website_exists = statusCode >= 200 && statusCode < 400;
  const loads_correctly = website_exists && cleaned.length > 200;
  const has_technical_problems = statusCode >= 400 || statusCode === 0 || cleaned.length < 50;

  return {
    json: {
      website_text: cleaned,
      restaurant_name: item.json['Restaurant Name'] || '',
      website_url: item.json['Website URL'] || '',
      'Row ID': item.json['Row ID'],
      website_exists,
      loads_correctly,
      has_technical_problems
    }
  };
});

const items = $input.all();
return items.map(item => {
  let rawText = item.json.output;
  rawText = rawText.replace(/```json|```/g, '').trim();
  const parsed = JSON.parse(rawText);
  return {
    json: {
      ...parsed,
      restaurant_name: item.json.restaurant_name || '',
      'Row ID': item.json['Row ID']
    }
  };
});

const emails = $('Get many messages').all();
const rows = $('Get row(s) in sheet1').all().filter(row => row.json["Email"]);
const results = [];
for (let i = 0; i < emails.length; i++) {
  const email = emails[i];
  const sender = email.json.From;
  const matchedRow = rows.find(row => 
    sender.includes(row.json["Email"])
  );
  if (matchedRow) {
    results.push({
      json: {
        sender: sender,
        subject: email.json.Subject,
        body: email.json.snippet,
        restaurant_name: matchedRow.json["Restaurant Name"],
        email: matchedRow.json["Email"],
        'Row ID': matchedRow.json["Row ID"]
      },
      pairedItem: { item: i }
    });
  }
}
return results.length > 0 ? results : [{ json: { no_match: true } }];

